  select count(*) into n from public.restaurants where country_code = 'SI' and michelin_stars = 2;
  if n <> 1 then raise exception 'SI: expected 1 2-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'SI' and michelin_stars = 1;
  if n <> 8 then raise exception 'SI: expected 8 1-star, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'SI' and michelin_keys = 3;
  if n <> 0 then raise exception 'SI: expected 0 3-Key hotels, found %', n; end if;
